/* Corresponds to zlib 1.2.3 trees.c build_tree (open-source zlib 1.2.3). Generated by km/libmatch.py: the upstream function with the declarations it uses, preprocessed, symbols renamed to the game's. gen_codes and bi_reverse are written out in place. Matches only under LTCG with pqdownheap and gen_bitlen. */
typedef unsigned char  Byte;
typedef unsigned int   uInt;
typedef unsigned long  uLong;
typedef Byte   Bytef;
typedef int    intf;
typedef void    *voidpf;
typedef voidpf (*alloc_func) (voidpf opaque, uInt items, uInt size);
typedef void   (*free_func)  (voidpf opaque, voidpf address);
typedef struct z_stream_s {
    Bytef    *next_in;
    uInt     avail_in;
    uLong    total_in;

    Bytef    *next_out;
    uInt     avail_out;
    uLong    total_out;

    char     *msg;
    struct internal_state  *state;

    alloc_func zalloc;
    free_func  zfree;
    voidpf     opaque;

    int     data_type;
    uLong   adler;
    uLong   reserved;
} z_stream;
typedef z_stream  *z_streamp;
typedef struct gz_header_s {
    int     text;
    uLong   time;
    int     xflags;
    int     os;
    Bytef   *extra;
    uInt    extra_len;
    uInt    extra_max;
    Bytef   *name;
    uInt    name_max;
    Bytef   *comment;
    uInt    comm_max;
    int     hcrc;
    int     done;

} gz_header;
typedef gz_header  *gz_headerp;
typedef unsigned char  uch;
typedef uch  uchf;
typedef unsigned short ush;
typedef ush  ushf;
typedef unsigned long  ulg;
typedef struct ct_data_s {
    union {
        ush  freq;
        ush  code;
    } fc;
    union {
        ush  dad;
        ush  len;
    } dl;
}  ct_data;
typedef struct static_tree_desc_s  static_tree_desc;
typedef struct tree_desc_s {
    ct_data *dyn_tree;
    int     max_code;
    static_tree_desc *stat_desc;
}  tree_desc;
typedef ush Pos;
typedef Pos  Posf;
typedef unsigned IPos;
typedef struct internal_state {
    z_streamp strm;
    int   status;
    Bytef *pending_buf;
    ulg   pending_buf_size;
    Bytef *pending_out;
    uInt   pending;
    int   wrap;
    gz_headerp  gzhead;
    uInt   gzindex;
    Byte  method;
    int   last_flush;

    uInt  w_size;
    uInt  w_bits;
    uInt  w_mask;

    Bytef *window;

    ulg window_size;

    Posf *prev;

    Posf *head;

    uInt  ins_h;
    uInt  hash_size;
    uInt  hash_bits;
    uInt  hash_mask;

    uInt  hash_shift;

    long block_start;

    uInt match_length;
    IPos prev_match;
    int match_available;
    uInt strstart;
    uInt match_start;
    uInt lookahead;

    uInt prev_length;

    uInt max_chain_length;

    uInt max_lazy_match;

    int level;
    int strategy;

    uInt good_match;

    int nice_match;

    struct ct_data_s dyn_ltree[(2*(256+1+29)+1)];
    struct ct_data_s dyn_dtree[2*30+1];
    struct ct_data_s bl_tree[2*19+1];

    struct tree_desc_s l_desc;
    struct tree_desc_s d_desc;
    struct tree_desc_s bl_desc;

    ush bl_count[15+1];

    int heap[2*(256+1+29)+1];
    int heap_len;
    int heap_max;

    uch depth[2*(256+1+29)+1];

    uchf *l_buf;

    uInt  lit_bufsize;

    uInt last_lit;

    ushf *d_buf;

    ulg opt_len;
    ulg static_len;
    uInt matches;
    int last_eob_len;

    ush bi_buf;

    int bi_valid;

}  deflate_state;
struct static_tree_desc_s {
    const ct_data *static_tree;
    const intf *extra_bits;
    int     extra_base;
    int     elems;
    int     max_length;
};
void pqdownheap     (deflate_state *s, ct_data *tree, int k);
void gen_bitlen     (deflate_state *s, tree_desc *desc);

void build_tree(s, desc)
    deflate_state *s;
    tree_desc *desc;
{
    ct_data *tree         = desc->dyn_tree;
    const ct_data *stree  = desc->stat_desc->static_tree;
    int elems             = desc->stat_desc->elems;
    int n, m;
    int max_code = -1;
    int node;

    s->heap_len = 0, s->heap_max = (2*(256+1+29)+1);

    for (n = 0; n < elems; n++) {
        if (tree[n].fc.freq != 0) {
            s->heap[++(s->heap_len)] = max_code = n;
            s->depth[n] = 0;
        } else {
            tree[n].dl.len = 0;
        }
    }

    while (s->heap_len < 2) {
        node = s->heap[++(s->heap_len)] = (max_code < 2 ? ++max_code : 0);
        tree[node].fc.freq = 1;
        s->depth[node] = 0;
        s->opt_len--; if (stree) s->static_len -= stree[node].dl.len;

    }
    desc->max_code = max_code;

    for (n = s->heap_len/2; n >= 1; n--) pqdownheap(s, tree, n);

    node = elems;
    do {
        { n = s->heap[1]; s->heap[1] = s->heap[s->heap_len--]; pqdownheap(s, tree, 1); };
        m = s->heap[1];

        s->heap[--(s->heap_max)] = n;
        s->heap[--(s->heap_max)] = m;

        tree[node].fc.freq = tree[n].fc.freq + tree[m].fc.freq;
        s->depth[node] = (uch)((s->depth[n] >= s->depth[m] ?
                                s->depth[n] : s->depth[m]) + 1);
        tree[n].dl.dad = tree[m].dl.dad = (ush)node;

        s->heap[1] = node++;
        pqdownheap(s, tree, 1);

    } while (s->heap_len >= 2);

    s->heap[--(s->heap_max)] = s->heap[1];

    gen_bitlen(s, (tree_desc *)desc);

    /* gen_codes((ct_data *)tree, max_code, s->bl_count), with bi_reverse, written out */
    {
        ush next_code[15+1];
        ush code = 0;
        int bits;

        for (bits = 1; bits <= 15; bits++) {
            next_code[bits] = code = (code + s->bl_count[bits-1]) << 1;
        }

        for (n = 0;  n <= max_code; n++) {
            int len = tree[n].dl.len;
            if (len == 0) continue;

            {
                unsigned c = next_code[len]++;
                int l = len;
                register unsigned res = 0;
                do {
                    res |= c & 1;
                    c >>= 1, res <<= 1;
                } while (--l > 0);
                tree[n].fc.code = res >> 1;
            }
        }
    }
}
